    """Translate common JSONC failures into the parser's hujson diagnostics."""
    pos = error.pos
    if pos >= len(text):
        if error.msg == "Expecting ',' delimiter":
            container = 'object' if text.lstrip().startswith('{') else 'array'
            state = f'parsing {container} after value'
        else:
