def _toon(text):
    """Check TOON's length annotated arrays and tabular blocks."""
    lines = text.splitlines()
    for i, line in enumerate(lines):
        # Tabular form: key[N]{field,...}: followed by N indented records.
        m = re.match(r'^\s*[^:#]+\[(\d+)\]\{([^}]*)\}\s*:\s*$', line)
        if m:
            expected = int(m.group(1))
            fields = [x.strip() for x in m.group(2).split(',')]
            count = 0
            for row_no, row in enumerate(lines[i+1:], i+2):
                if not row.strip():
                    if count: break
                    continue
                if len(row)-len(row.lstrip()) == 0: break
                try: width = len(next(csv.reader([row])))
                except Exception: width = len(row.split(','))
                if width != len(fields):
                    return f'line {row_no}: tabular row width mismatch'
                count += 1
            if count < expected:
                return f'line {i+2}: tabular length mismatch; expected {expected} rows'
            if count > expected:
                return f'line {i+1+expected+1}: too many tabular rows (expected {expected})'
        # Inline array form: key[N]: a, b, ...
        m = re.match(r'^\s*[^:#]+\[(\d+)\]\s*:\s*(.*)$', line)
        if m:
